input.query:
Gong__Primary_Opportunity__c != null
  AND Gong__Scope__c = 'External'
  AND Gong__Call_Duration_sec__c >= 120
  AND Gong__Call_Start__c >= #{_dp('{"pill_type":"output","provider":"workato_custom_code","line":"2e1066db","path":["output","week_start"]}')}
  AND Gong__Call_Start__c < #{_dp('{"pill_type":"output","provider":"workato_custom_code","line":"2e1066db","path":["output","week_end"]}')}
ORDER BY Gong__Call_Start__c DESC

